SELECT id, code, DATE_FORMAT( create_time, "%Y-%m-%d %H:%i:%S" ) AS 'create_time', DATE_FORMAT( update_time, "%Y-%m-%d %H:%i:%S" ) AS 'update_time', DATE_FORMAT( start_time, "%Y-%m-%d %H:%i:%S" ) AS 'start_time', DATE_FORMAT( end_time, "%Y-%m-%d %H:%i:%S" ) AS 'end_time', task_name, url, auth, agent_id, type, state_id, message
FROM yz_sms_bulk_business
ORDER BY create_time DESC LIMIT #{StarRow},#{PageSize}

SELECT id FROM yz_sms_bulk_business
and agent_id in
#{agent_id}

SELECT id, message, create_time, type FROM yz_sms_bulk_business
state_id = 3 and type = #{type}
and id not in
#{exIdArr}
ORDER BY create_time ASC LIMIT 1
